#include "morfo_pre.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
#include <stdexcept>

namespace morfo::pre {namespace {
double distance(const Descriptor& a,const Descriptor& b){double sum=0;for(std::size_t i=0;i<a.values.size();++i){const double d=a.values[i]-b.values[i];sum+=d*d;}return std::sqrt(sum);}
Descriptor describe(std::size_t width,std::size_t height,const std::vector<unsigned char>& rgba,std::size_t x0,std::size_t y0,std::size_t w,std::size_t h){Descriptor d;double lum=0,lum2=0,edges=0;const double count=double(w*h);for(std::size_t y=y0;y<y0+h;++y)for(std::size_t x=x0;x<x0+w;++x){const auto i=(y*width+x)*4;const double r=rgba[i]/255.0,g=rgba[i+1]/255.0,b=rgba[i+2]/255.0,l=.2126*r+.7152*g+.0722*b;d.values[0]+=r;d.values[1]+=g;d.values[2]+=b;lum+=l;lum2+=l*l;if(x>x0){const auto j=i-4;edges+=std::abs(l-(.2126*rgba[j]/255.0+.7152*rgba[j+1]/255.0+.0722*rgba[j+2]/255.0));}if(y>y0){const auto j=i-width*4;edges+=std::abs(l-(.2126*rgba[j]/255.0+.7152*rgba[j+1]/255.0+.0722*rgba[j+2]/255.0));}}d.values[0]/=count;d.values[1]/=count;d.values[2]/=count;d.values[3]=lum/count;d.values[4]=std::sqrt(std::max(0.0,lum2/count-d.values[3]*d.values[3]));d.values[5]=edges/std::max(1.0,2*count-w-h);d.values[6]=double(x0+w/2)/width;d.values[7]=double(y0+h/2)/height;return d;}
}
Result perceive(std::size_t width,std::size_t height,const std::vector<unsigned char>& rgba,Config config){if(!width||!height||rgba.size()!=width*height*4)throw std::invalid_argument("PRE-001 requires an RGBA image");if(config.cell<4||config.clusters<2||config.iterations<1)throw std::invalid_argument("Invalid PRE-001 configuration");Result out;out.width=width;out.height=height;out.columns=(width+config.cell-1)/config.cell;out.rows=(height+config.cell-1)/config.cell;for(std::size_t y=0;y<height;y+=config.cell)for(std::size_t x=0;x<width;x+=config.cell){const auto w=std::min(config.cell,width-x),h=std::min(config.cell,height-y);out.cells.push_back({x,y,w,h,0,0,0,describe(width,height,rgba,x,y,w,h)});}const auto k=std::min(config.clusters,out.cells.size());out.prototypes.push_back(out.cells.front().descriptor);while(out.prototypes.size()<k){std::size_t best=0;double farthest=-1;for(std::size_t i=0;i<out.cells.size();++i){double nearest=std::numeric_limits<double>::max();for(const auto& p:out.prototypes)nearest=std::min(nearest,distance(out.cells[i].descriptor,p));if(nearest>farthest){farthest=nearest;best=i;}}out.prototypes.push_back(out.cells[best].descriptor);}for(std::size_t iteration=0;iteration<config.iterations;++iteration){bool changed=false;std::vector<Descriptor> sums(k);std::vector<std::size_t> counts(k);for(auto& cell:out.cells){std::size_t best=0;double nearest=distance(cell.descriptor,out.prototypes[0]);for(std::size_t c=1;c<k;++c){const auto candidate=distance(cell.descriptor,out.prototypes[c]);if(candidate<nearest){nearest=candidate;best=c;}}changed|=cell.cluster!=best;cell.cluster=best;cell.distance=nearest;++counts[best];for(std::size_t f=0;f<8;++f)sums[best].values[f]+=cell.descriptor.values[f];}for(std::size_t c=0;c<k;++c)if(counts[c])for(std::size_t f=0;f<8;++f)out.prototypes[c].values[f]=sums[c].values[f]/counts[c];if(!changed&&iteration)break;}std::vector<double> mean(k),spread(k);std::vector<std::size_t> counts(k);for(auto& cell:out.cells){cell.distance=distance(cell.descriptor,out.prototypes[cell.cluster]);mean[cell.cluster]+=cell.distance;++counts[cell.cluster];}for(std::size_t c=0;c<k;++c)if(counts[c])mean[c]/=counts[c];for(const auto& cell:out.cells){const auto delta=cell.distance-mean[cell.cluster];spread[cell.cluster]+=delta*delta;}for(std::size_t c=0;c<k;++c)spread[c]=counts[c]>1?std::sqrt(spread[c]/counts[c]):0;for(auto& cell:out.cells)cell.novelty=spread[cell.cluster]>1e-9?std::max(0.0,(cell.distance-mean[cell.cluster])/spread[cell.cluster]):0;return out;}
}
